UPDATE email_sequences
SET
  steps = '[
    {"type":"send_email","from_name":"VantoOS Team","subject":"Welcome to VantoOS — Your AI Executive Assistant Starts Now 🚀","content":"<p>Hi {{first_name}},</p><p>Welcome to VantoOS — your new AI-powered Executive Operating System.</p><p>Think of VantoOS as your personal chief of staff that lives on your phone or computer. It helps you plan your day, manage projects, track your money, handle emails, and make smarter decisions — all in one place.</p><p><strong>TODAY''S TASK:</strong> Log in and explore your Dashboard.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/\">https://executive.onlinecourseformlm.com/</a></p><p>Your Dashboard is your command centre. It''s the first thing you see when you log in. Here''s what to look for:</p><ul><li>Summary cards at the top — these show your tasks, meetings, and financial overview at a glance</li><li>Recent activity feed — what''s been happening across your projects</li><li>AI insights — smart suggestions to help you stay ahead</li></ul><p>Just log in, look around, and get comfortable. Tomorrow we''ll show you how to plan your day.</p><p>You''ve got this!<br/>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 2: Plan Your Day Like a Pro — Tasks, Meetings & Reminders","content":"<p>Hi {{first_name}},</p><p>Today we''re showing you the most powerful part of VantoOS — the Plan Hub.</p><p>This is where you organise everything: tasks, meetings, reminders, notes, and your calendar. All in one place.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/plan\">https://executive.onlinecourseformlm.com/plan</a></p><p><strong>HERE''S WHAT TO DO TODAY:</strong></p><ol><li>Click the \"Tasks\" tab at the top</li><li>Click \"+ Add Task\"</li><li>Type something you need to do today (e.g., \"Review quarterly report\")</li><li>Set the priority to \"High\" and save it</li></ol><p>That''s it! You just created your first task.</p><p><strong>BONUS:</strong> Try clicking the \"Meetings\" tab and add an upcoming meeting. VantoOS will automatically create a reminder 1 hour before it starts.</p><p>💡 <strong>TIP:</strong> You''ll see tabs for Tasks, Meetings, Reminders, Notes, and Calendar — each one helps you stay organised. Explore them at your own pace.</p><p>Tomorrow: We''ll show you how to take notes and let AI extract action items for you.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 3: Take Notes & Let AI Find Your Action Items 📝","content":"<p>Hi {{first_name}},</p><p>Ever been in a meeting and forgotten what you promised to do? VantoOS fixes that.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/plan?tab=notes\">https://executive.onlinecourseformlm.com/plan?tab=notes</a></p><p><strong>TODAY''S TASK:</strong> Write your first daily note.</p><ol><li>Go to the Notes tab in your Plan Hub</li><li>Type anything — meeting notes, ideas, to-dos, thoughts for the day</li><li>Your note saves automatically</li></ol><p><strong>HERE''S THE MAGIC:</strong> See the \"Extract Actions\" button? Click it and VantoOS AI will read your notes and pull out any action items, turning them into tasks automatically.</p><p>For example, if you wrote \"Need to call John about the contract by Friday\" — the AI will create a task for that.</p><p>💡 <strong>TIP:</strong> You can also use the microphone icon to dictate notes hands-free. Perfect for when you''re driving or in a meeting.</p><p>Tomorrow: Managing your email like a superhero.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 4: Master Your Email Inbox in Minutes ✉️","content":"<p>Hi {{first_name}},</p><p>Email overload is real. VantoOS helps you handle it faster than ever.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/email\">https://executive.onlinecourseformlm.com/email</a></p><p><strong>TODAY''S TASK:</strong> Explore your Smart Inbox.</p><p>Your email section is designed for speed. Here''s how it works:</p><ul><li>Your emails are sorted by account (Gov, Business, Personal) — or view them all at once</li><li>Each email shows its urgency level and what action it needs</li><li>Use keyboard shortcuts for lightning-fast management:<ul><li>J/K = move up and down through emails</li><li>Enter = open an email</li><li>E = archive it (done!)</li><li>S = snooze it for later</li></ul></li></ul><p>💡 <strong>TIP:</strong> Press Ctrl+K (or ⌘K on Mac) to open the Command Bar — it lets you create tasks from emails, snooze with custom times, and more.</p><p>Look for the 🎓 tutorial icon when you first open the email page — it''ll walk you through everything in 60 seconds.</p><p>Tomorrow: Taking control of your finances.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 5: Track Your Money — Income, Expenses & Budgets 💰","content":"<p>Hi {{first_name}},</p><p>Money matters. VantoOS gives you a clear picture of where your money comes from and where it goes.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/finance\">https://executive.onlinecourseformlm.com/finance</a></p><p><strong>TODAY''S TASK:</strong> Add your first income stream.</p><ol><li>Go to the Finance page</li><li>Look at the Overview — it shows your monthly snapshot</li><li>Click on \"Income Streams\" and add at least one source (salary, freelance work, investments, etc.)</li><li>Then check out \"Expenses\" and log one recent expense</li></ol><p><strong>WHAT ELSE IS HERE:</strong></p><ul><li>📋 Budget tab — set up recurring bills so you never miss a payment</li><li>🏦 Bank Import — upload a CSV bank statement and VantoOS will categorise your transactions automatically</li><li>🤖 AI Finance Mentor — get personalised financial advice based on YOUR data</li></ul><p>💡 <strong>TIP:</strong> All amounts default to South African Rand (ZAR). You can change your currency in your finance profile.</p><p>Tomorrow: Managing your projects like a CEO.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 6: Your Projects Command Centre 📂","content":"<p>Hi {{first_name}},</p><p>Whether you run a business, lead a team, or manage side hustles — VantoOS helps you track every project in one place.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/projects\">https://executive.onlinecourseformlm.com/projects</a></p><p><strong>TODAY''S TASK:</strong> Create your first project.</p><ol><li>Click \"+ New Project\"</li><li>Give it a name and a short description</li><li>Set the status (active, planning, on hold, etc.)</li></ol><p><strong>ONCE YOUR PROJECT IS CREATED, you can:</strong></p><ul><li>Add tasks specifically for that project</li><li>Write project notes</li><li>Save important links</li><li>Log accomplishments (wins!)</li><li>Talk to an AI Partner that gives strategic advice just for that project</li></ul><p>📌 Pin your most important projects to keep them at the top.</p><p>🚫 If something is blocking a project, mark it as \"Blocked\" — add who/what is stopping progress and when you expect it to be resolved.</p><p>Tomorrow: Meet your AI strategic advisor.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 7: Your AI Partner — Strategic Advice Across All Projects 🤖","content":"<p>Hi {{first_name}},</p><p>Imagine having a strategic advisor who knows every one of your projects and can tell you exactly where to focus. That''s your Portfolio Partner.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/dashboard/partner\">https://executive.onlinecourseformlm.com/dashboard/partner</a></p><p><strong>TODAY''S TASK:</strong> Ask your AI Partner a question.</p><p>Your Portfolio Partner analyses ALL your projects and gives you insights on:</p><ul><li>Which project has the most momentum</li><li>Where the biggest risks are</li><li>What you should focus on this week</li></ul><p>Try asking it:</p><ul><li>\"Which project needs my attention right now?\"</li><li>\"What are my biggest risks?\"</li><li>\"What should I focus on this week?\"</li></ul><p>💡 <strong>TIP:</strong> The more you use VantoOS (adding tasks, notes, project updates), the smarter your Partner becomes. It learns from your activity to give increasingly relevant advice.</p><p>Tomorrow: Building your second brain with the Knowledge Base.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 8: Your Knowledge Base — Upload Documents & Ask Questions 🧠","content":"<p>Hi {{first_name}},</p><p>What if you could upload any document — a contract, a business plan, a policy — and then just ASK it questions? That''s the Knowledge Base.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/knowledge\">https://executive.onlinecourseformlm.com/knowledge</a></p><p><strong>TODAY''S TASK:</strong> Upload your first document.</p><ol><li>Click \"Upload\" and select a PDF or text file</li><li>Wait for it to be indexed (this takes a few seconds)</li><li>Then type a question about the document in the search box</li></ol><p>For example:</p><ul><li>\"What does my contract say about termination?\"</li><li>\"Summarise the key points of this report\"</li><li>\"What are the payment terms?\"</li></ul><p>Your documents are securely stored and only you can access them. The AI uses them to give you better, more informed answers across VantoOS.</p><p>💡 <strong>TIP:</strong> Upload your most important business documents — contracts, proposals, research. The more context VantoOS has, the better it can help you.</p><p>Tomorrow: Planning your trips and purchases.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 9: Travel Plans & Shopping Lists — Life Admin Made Easy ✈️🛒","content":"<p>Hi {{first_name}},</p><p>VantoOS isn''t just for work — it helps you manage life admin too.</p><p><strong>TRAVEL ✈️</strong><br/>👉 <a href=\"https://executive.onlinecourseformlm.com/travel\">https://executive.onlinecourseformlm.com/travel</a></p><ul><li>Add upcoming trips with destinations, dates, and notes</li><li>Track travel budgets and bookings</li><li>Link travel to specific projects if it''s a business trip</li></ul><p><strong>SHOPPING 🛒</strong><br/>👉 <a href=\"https://executive.onlinecourseformlm.com/shopping\">https://executive.onlinecourseformlm.com/shopping</a></p><ul><li>Create shopping lists with items, prices, and links</li><li>Mark items as purchased when done</li><li>Organise by category to keep things tidy</li><li>Link purchases to projects if they''re project-related</li></ul><p><strong>TODAY''S TASK:</strong> Add one upcoming trip OR create a shopping list with 3 items you need to buy.</p><p>💡 <strong>TIP:</strong> More AI-powered features for travel planning are coming soon!</p><p>Tomorrow: Your final lesson — settings, reports, and becoming a power user.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 10: You''re a VantoOS Power User Now! ⚡ Final Tips & Settings","content":"<p>Hi {{first_name}},</p><p>Congratulations! You''ve made it through 10 days of VantoOS onboarding. Let''s wrap up with a few power-user tips.</p><p><strong>SETTINGS ⚙️</strong><br/>👉 <a href=\"https://executive.onlinecourseformlm.com/settings\">https://executive.onlinecourseformlm.com/settings</a></p><ul><li>Complete your Profile Wizard — this helps the AI understand your industry, role, and preferences</li><li>To guarantee absolute data sovereignty for this private cohort, a personal OpenAI or Gemini key is required. Go to Settings → AI Keys to connect yours.</li></ul><p><strong>REPORTS 📊</strong><br/>👉 <a href=\"https://executive.onlinecourseformlm.com/investor-report\">https://executive.onlinecourseformlm.com/investor-report</a></p><ul><li>Generate weekly reports that summarise your accomplishments, upcoming work, and blockers</li><li>Create investor-ready reports to share with stakeholders</li><li>The AI pulls data from your tasks, projects, meetings, and finances automatically</li></ul><p>💡 <strong>PRO TIP:</strong> Generate a weekly report every Friday. It keeps you accountable and helps you see progress over time.</p><p><strong>NEED HELP ANYTIME?</strong></p><ul><li>Look for the ❓ button on any page — it gives you step-by-step guidance</li><li>Visit the User Manual: <a href=\"https://executive.onlinecourseformlm.com/manual\">https://executive.onlinecourseformlm.com/manual</a></li><li>Download the manual to read offline</li></ul><p>Thank you for being a beta tester. Your feedback shapes the future of VantoOS.</p><p>Welcome to the future of executive productivity.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 11: Become Your Own CFO — Budgets, Bank Imports & AI Finance Mentor 📊","content":"<p>Hi {{first_name}},</p><p>On Day 5 you got a taste of VantoOS Finance. Today we go deeper — into the tools that turn you into your own CFO.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/finance\">https://executive.onlinecourseformlm.com/finance</a></p><p><strong>THREE POWER FEATURES TO EXPLORE TODAY:</strong></p><p><strong>1️⃣ BUDGET COMMAND CENTRE</strong></p><ul><li>Click the \"Budget\" tab</li><li>Add a recurring bill (rent, internet, insurance — anything you pay regularly)</li><li>Set the cadence (monthly, yearly, or custom) and the due day</li><li>VantoOS will auto-generate payment events AND warn you 7 days before each one is due</li><li>Toggle \"Autopay\" on items that debit automatically so you know what''s manual vs automatic</li></ul><p><strong>2️⃣ BANK STATEMENT IMPORT</strong></p><ul><li>Click the \"Bank Import\" tab</li><li>Upload a CSV bank statement from your bank</li><li>VantoOS will parse every transaction, detect merchants, and auto-categorise them (groceries, transport, subscriptions, etc.)</li><li>You can create custom merchant rules so future imports categorise perfectly</li></ul><p><strong>3️⃣ AI FINANCE MENTOR</strong></p><ul><li>Click the 🤖 icon in the Finance section</li><li>Ask questions like:<ul><li>\"Where am I overspending?\"</li><li>\"Can I afford to hire someone next month?\"</li><li>\"What''s my savings rate?\"</li></ul></li><li>The mentor analyses YOUR actual data — income streams, expenses, debts, and budget — to give personalised advice</li></ul><p>💡 <strong>TIP:</strong> Log your debts too (Finance → Debts). The AI Mentor factors them into its advice, giving you a complete financial picture.</p><p>Tomorrow: Managing government tenders like a pro with TenderOS.</p><p>The VantoOS Team</p>"},
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 12: Win More Tenders with TenderOS — Your Bid Command Centre 🏛️","content":"<p>Hi {{first_name}},</p><p>If you bid on government or corporate tenders, this is the feature you''ve been waiting for. TenderOS turns the chaos of tender management into a structured, AI-assisted process.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/projects\">https://executive.onlinecourseformlm.com/projects</a> (create a new project → select \"TenderOS\" as the solution type)</p><p><strong>HERE''S HOW TO GET STARTED:</strong></p><p><strong>1️⃣ CREATE A TENDER PROJECT</strong></p><ul><li>Go to Projects → \"+ New Project\"</li><li>Give it the tender name (e.g., \"DOH Medical Supplies RFQ 2026\")</li><li>Select \"TenderOS\" as the solution type</li></ul><p><strong>2️⃣ UPLOAD THE TENDER DOCUMENT</strong></p><ul><li>Open your new TenderOS project</li><li>Go to the \"Tender Brief\" tab and upload the actual tender PDF</li><li>The AI will read the document and extract:<ul><li>Key requirements (mandatory vs optional)</li><li>Submission deadlines</li><li>Compliance documents needed</li><li>Evaluation criteria and weightings</li></ul></li></ul><p><strong>3️⃣ CHECK YOUR BID READINESS SCORE</strong></p><ul><li>VantoOS calculates a real-time Bid Readiness Score based on:<ul><li>40% Requirements coverage — have you addressed every requirement?</li><li>40% Compliance — are your documents (BEE cert, tax clearance, CSD registration) uploaded and valid?</li><li>20% Pricing — is your pricing model complete?</li></ul></li><li>Your score updates as you work, so you always know where you stand</li></ul><p><strong>4️⃣ COMPLIANCE VAULT</strong></p><ul><li>Upload your compliance documents (BEE certificate, tax clearance, company registration, etc.)</li><li>VantoOS tracks expiry dates and warns you before anything lapses</li><li>No more losing bids because of an expired document!</li></ul><p><strong>5️⃣ AI TENDER ASSISTANT</strong></p><ul><li>Ask the AI questions about the tender document:<ul><li>\"What are the mandatory requirements?\"</li><li>\"Summarise the evaluation criteria\"</li><li>\"What compliance documents do I need?\"</li></ul></li><li>Every AI answer includes citations from the actual tender document — zero hallucination, fully grounded</li></ul><p>💡 <strong>TIP:</strong> Pin your active tenders to keep them at the top of your Projects list. Use the deadline reminders to never miss a submission date.</p><p>🎉 <strong>That''s the end of your onboarding journey!</strong> You now know every major feature in VantoOS.</p><p>Remember:</p><ul><li>❓ Help button on every page for step-by-step guidance</li><li>📖 User Manual: <a href=\"https://executive.onlinecourseformlm.com/manual\">https://executive.onlinecourseformlm.com/manual</a></li><li>🤖 Your AI Portfolio Partner gets smarter the more you use VantoOS</li></ul><p>Welcome to the future of executive productivity.</p><p>The VantoOS Team</p>"}
  ]'::jsonb,
  updated_at = now()
WHERE id = '0f23eef6-6c16-4f9f-9357-8a67e358abe2';